<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 25;
const int INF = 10007;
const int MAXT = 65;
const int MAXC = 12;

int n, k;
string Sgrid[MAXN], Tgrid[MAXN];
int distZ[MAXN][MAXN];
int dp[MAXT][MAXC][MAXC][MAXC][MAXC];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};
vector<pair<int,int>> starts, ends;

struct Dinic {
    struct Edge {
        int to, rev, cap;
    };
    int n;
    vector<vector<Edge>> g;
    vector<int> level, ptr;

    Dinic(int n) : n(n), g(n), level(n), ptr(n) {}

    void addEdge(int v, int to, int cap) {
        Edge a{to, (int)g[to].size(), cap};
        Edge b{v, (int)g[v].size(), 0};
        g[v].push_back(a);
        g[to].push_back(b);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (const Edge &e : g[v]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int v, int t, int pushed) {
        if (pushed == 0) return 0;
        if (v == t) return pushed;
        for (int &cid = ptr[v]; cid < (int)g[v].size(); ++cid) {
            Edge &e = g[v][cid];
            if (level[e.to] != level[v] + 1 || e.cap <= 0) continue;
            int tr = dfs(e.to, t, min(pushed, e.cap));
            if (tr == 0) continue;
            e.cap -= tr;
            g[e.to][e.rev].cap += tr;
            return tr;
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int flow = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (int pushed = dfs(s, t, 1000000000))
                flow += pushed;
        }
        return flow;
    }
};

void bfsFromZ(int sx, int sy) {
    memset(distZ, -1, sizeof distZ);
    queue<pair<int,int>> q;
    distZ[sx][sy] = 0;
    q.push({sx, sy});
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (distZ[nx][ny] != -1) continue;
            if (Tgrid[nx][ny] == 'Y' || Tgrid[nx][ny] == 'Z') continue;
            distZ[nx][ny] = distZ[x][y] + 1;
            q.push({nx, ny});
        }
    }
}

int ok(int t, int x0, int y0, int x, int y) {
    if (distZ[x0][y0] < t) return 0;
    if (x0 == x && y0 == y) return 1;
    if (t >= k) return 0;
    if (distZ[x0][y0] <= t) return 0;
    int &res = dp[t][x0][y0][x][y];
    if (res != -1) return res;
    for (int d = 0; d < 4; ++d) {
        int nx = x0 + dx[d];
        int ny = y0 + dy[d];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
        if (Sgrid[nx][ny] == 'Y' || Sgrid[nx][ny] == 'Z') continue;
        if (ok(t + 1, nx, ny, x, y)) return res = 1;
    }
    return res = 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    memset(dp, -1, sizeof dp);
    cin >> n >> k;
    for (int i = 0; i < n; ++i) cin >> Sgrid[i];
    for (int i = 0; i < n; ++i) cin >> Tgrid[i];

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (Tgrid[i][j] == 'Z') zx = i, zy = j;

    bfsFromZ(zx, zy);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distZ[i][j] == -1) distZ[i][j] = INF;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = Sgrid[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') starts.push_back({i, j});
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = Tgrid[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') ends.push_back({i, j});
        }

    int S = 0;
    int T = (int)starts.size() + (int)ends.size() + 1;
    Dinic dinic(T + 1);

    for (int i = 0; i < (int)starts.size(); ++i)
        dinic.addEdge(S, i + 1, Sgrid[starts[i].first][starts[i].second] - '0');

    for (int i = 0; i < (int)ends.size(); ++i)
        dinic.addEdge((int)starts.size() + i + 1, T,
                      Tgrid[ends[i].first][ends[i].second] - '0');

    for (int i = 0; i < (int)starts.size(); ++i)
        for (int j = 0; j < (int)ends.size(); ++j)
            if (ok(0, starts[i].first, starts[i].second,
                   ends[j].first, ends[j].second))
                dinic.addEdge(i + 1, (int)starts.size() + j + 1, INF);

    cout << dinic.maxFlow(S, T) << '\n';
    return 0;
}
